//! Transport trust: the built-in transport CA and client/server certificate
//! issuance created at install time and used for mandatory mTLS.
//!
//! The transport CA key is generated by `keywright install`, encrypted at
//! rest with age (identities live in the broker's protected data dir), and
//! never exposed to agent-role identities. Client certificates carry their
//! role in a dedicated X.509 extension so the broker can map a validated
//! peer identity to a [Role] without any out-of-band lookup.

use crate::role::Role;
use openssl::asn1::Asn1Time;
use openssl::bn::{BigNum, MsbOption};
use openssl::error::ErrorStack;
use openssl::hash::MessageDigest;
use openssl::nid::Nid;
use openssl::pkey::{PKey, Private, Public};
use openssl::rsa::Rsa;
use openssl::x509::extension::{
    BasicConstraints, ExtendedKeyUsage, KeyUsage, SubjectAlternativeName,
};
use openssl::x509::{X509, X509Builder, X509NameBuilder};
use serde::{Deserialize, Serialize};
use std::time::{SystemTime, UNIX_EPOCH};

/// Days covered by the transport CA certificate.
pub const CA_VALIDITY_DAYS: u32 = 3650;
/// Days covered by issued client/server certificates.
pub const LEAF_VALIDITY_DAYS: u32 = 365;

/// Organizational Unit DN value marking an agent-role client certificate.
pub const ROLE_OU_AGENT: &str = "keywright-agent";
/// Organizational Unit DN value marking an admin-role client certificate.
pub const ROLE_OU_ADMIN: &str = "keywright-admin";

/// The role is bound into the subject DN's OU field rather than a custom
/// extension: the openssl bindings expose DN reading for X.509 certificates
/// but no generic extension iteration. The binding is still unforgeable in
/// practice because the broker only trusts certificates chaining to the
/// transport CA it generated at install time.

#[derive(Debug, thiserror::Error)]
pub enum TrustError {
    #[error("openssl operation failed: {0}")]
    OpenSsl(#[from] ErrorStack),
    #[error("certificate parse failed: {0}")]
    Parse(String),
    #[error("certificate presented no usable identity (missing CN or role)")]
    NoIdentity,
    #[error("role extension is invalid: {0}")]
    InvalidRole(String),
}

/// PEM-encoded transport material, ready for protected at-rest storage.
///
/// Private key PEM is always encrypted by the caller before it touches disk
/// (age/SOPS); these types just delimit the material.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CaMaterial {
    /// PEM of the CA certificate (public).
    pub cert_pem: String,
    /// PEM of the CA private key — MUST be age-encrypted at rest.
    pub key_pem: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct IssuedCert {
    /// PEM of the issued certificate (public).
    pub cert_pem: String,
    /// PEM of the private key — MUST be age-encrypted at rest.
    pub key_pem: String,
    /// Role bound into the certificate (client certs only), for audit.
    pub role: Role,
}

/// Identity extracted from a validated peer certificate.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct PeerIdentity {
    /// Common Name of the client certificate (stable per enrollment).
    pub common_name: String,
    pub role: Role,
}

fn now_plus_days(days: u32) -> Result<Asn1Time, TrustError> {
    let secs = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_err(|e| TrustError::Parse(format!("clock error: {e}")))?
        .as_secs() as i64
        + i64::from(days) * 86_400;
    Asn1Time::from_unix(secs).map_err(|e| TrustError::Parse(format!("time conversion: {e}")))
}

fn new_serial() -> Result<openssl::asn1::Asn1Integer, TrustError> {
    let mut bn = BigNum::new()?;
    bn.rand(128, MsbOption::MAYBE_ZERO, false)?;
    Ok(bn.to_asn1_integer()?)
}

fn transport_name(common_name: &str) -> Result<openssl::x509::X509Name, TrustError> {
    transport_name_with_role(common_name, None)
}

fn transport_name_with_role(
    common_name: &str,
    role_ou: Option<&str>,
) -> Result<openssl::x509::X509Name, TrustError> {
    let mut name = X509NameBuilder::new()?;
    name.append_entry_by_text("CN", common_name)?;
    if let Some(ou) = role_ou {
        name.append_entry_by_text("OU", ou)?;
    }
    name.append_entry_by_text("O", "keywright-transport")?;
    Ok(name.build())
}

/// Generate a fresh transport CA (RSA 3072, self-signed, CA:TRUE).
pub fn generate_transport_ca(common_name: &str) -> Result<CaMaterial, TrustError> {
    let rsa = Rsa::generate(3072)?;
    let key = PKey::from_rsa(rsa)?;
    let name = transport_name(common_name)?;

    let mut builder = X509Builder::new()?;
    builder.set_version(2)?;
    builder.set_serial_number(&*new_serial()?)?;
    builder.set_subject_name(&name)?;
    builder.set_issuer_name(&name)?;
    builder.set_pubkey(&key)?;
    builder.set_not_before(&*Asn1Time::days_from_now(0)?)?;
    builder.set_not_after(&*now_plus_days(CA_VALIDITY_DAYS)?)?;
    builder.append_extension(BasicConstraints::new().critical().ca().build()?)?;
    builder.append_extension(
        KeyUsage::new()
            .critical()
            .digital_signature()
            .key_cert_sign()
            .crl_sign()
            .build()?,
    )?;
    builder.sign(&key, MessageDigest::sha256())?;
    let cert = builder.build();

    Ok(CaMaterial {
        cert_pem: String::from_utf8_lossy(&cert.to_pem()?).into_owned(),
        key_pem: String::from_utf8_lossy(&key.private_key_to_pem_pkcs8()?).into_owned(),
    })
}

/// Parse a PEM certificate; errors are parse failures only.
pub fn parse_cert(pem: &str) -> Result<X509, TrustError> {
    X509::from_pem(pem.as_bytes()).map_err(|e| TrustError::Parse(e.to_string()))
}

/// Parse a PEM private key.
pub fn parse_key(pem: &str) -> Result<PKey<Private>, TrustError> {
    PKey::private_key_from_pem(pem.as_bytes()).map_err(|e| TrustError::Parse(e.to_string()))
}

/// Extract the role from a certificate's OU DN entry.
pub fn role_from_cert(cert: &X509) -> Result<Role, TrustError> {
    let mut found: Option<Role> = None;
    for entry in cert
        .subject_name()
        .entries_by_nid(Nid::ORGANIZATIONALUNITNAME)
    {
        let value = entry.data().to_string().map_err(TrustError::OpenSsl)?;
        let role = match value.as_str() {
            ROLE_OU_AGENT => Role::Agent,
            ROLE_OU_ADMIN => Role::Admin,
            _ => continue,
        };
        if found.replace(role).is_some() {
            return Err(TrustError::InvalidRole("multiple role OU entries".into()));
        }
    }
    found.ok_or(TrustError::NoIdentity)
}

/// Extract the full peer identity (CN + role) from a certificate.
pub fn identity_from_cert(cert: &X509) -> Result<PeerIdentity, TrustError> {
    let cn = cert
        .subject_name()
        .entries_by_nid(Nid::COMMONNAME)
        .next()
        .map(|e| e.data().to_string().map_err(TrustError::OpenSsl))
        .transpose()?
        .ok_or(TrustError::NoIdentity)?;
    let role = role_from_cert(cert)?;
    Ok(PeerIdentity {
        common_name: cn,
        role,
    })
}

fn role_ou(role: Role) -> &'static str {
    match role {
        Role::Agent => ROLE_OU_AGENT,
        Role::Admin => ROLE_OU_ADMIN,
    }
}

/// Issue a client certificate binding `common_name` to `role`, signed by the
/// transport CA. This is the enroll path — human-controlled.
pub fn issue_client_cert(
    ca: &CaMaterial,
    common_name: &str,
    role: Role,
) -> Result<IssuedCert, TrustError> {
    let ca_cert = parse_cert(&ca.cert_pem)?;
    let ca_key = parse_key(&ca.key_pem)?;

    let rsa = Rsa::generate(2048)?;
    let key = PKey::from_rsa(rsa)?;
    let name = transport_name_with_role(common_name, Some(role_ou(role)))?;

    let mut builder = X509Builder::new()?;
    builder.set_version(2)?;
    builder.set_serial_number(&*new_serial()?)?;
    builder.set_subject_name(&name)?;
    builder.set_issuer_name(ca_cert.subject_name())?;
    builder.set_pubkey(&key)?;
    builder.set_not_before(&*Asn1Time::days_from_now(0)?)?;
    builder.set_not_after(&*now_plus_days(LEAF_VALIDITY_DAYS)?)?;
    builder.append_extension(BasicConstraints::new().build()?)?;
    builder.append_extension(
        KeyUsage::new()
            .critical()
            .digital_signature()
            .key_encipherment()
            .build()?,
    )?;
    builder.append_extension(ExtendedKeyUsage::new().client_auth().build()?)?;
    builder.sign(&ca_key, MessageDigest::sha256())?;
    let cert = builder.build();

    Ok(IssuedCert {
        cert_pem: String::from_utf8_lossy(&cert.to_pem()?).into_owned(),
        key_pem: String::from_utf8_lossy(&key.private_key_to_pem_pkcs8()?).into_owned(),
        role,
    })
}

/// Issue the broker's own server certificate (serverAuth, SANs for the
/// bound hostnames — loopback by default).
pub fn issue_server_cert(ca: &CaMaterial, hostnames: &[&str]) -> Result<IssuedCert, TrustError> {
    let ca_cert = parse_cert(&ca.cert_pem)?;
    let ca_key = parse_key(&ca.key_pem)?;

    let rsa = Rsa::generate(2048)?;
    let key = PKey::from_rsa(rsa)?;
    let primary = hostnames.first().copied().unwrap_or("localhost");
    let name = transport_name(primary)?;

    let mut builder = X509Builder::new()?;
    builder.set_version(2)?;
    builder.set_serial_number(&*new_serial()?)?;
    builder.set_subject_name(&name)?;
    builder.set_issuer_name(ca_cert.subject_name())?;
    builder.set_pubkey(&key)?;
    builder.set_not_before(&*Asn1Time::days_from_now(0)?)?;
    builder.set_not_after(&*now_plus_days(LEAF_VALIDITY_DAYS)?)?;
    builder.append_extension(BasicConstraints::new().build()?)?;
    builder.append_extension(
        KeyUsage::new()
            .critical()
            .digital_signature()
            .key_encipherment()
            .build()?,
    )?;
    builder.append_extension(ExtendedKeyUsage::new().server_auth().build()?)?;
    let mut san = SubjectAlternativeName::new();
    for h in hostnames {
        san.dns(h);
    }
    let ctx = builder.x509v3_context(Some(&ca_cert), None);
    builder.append_extension(san.build(&ctx)?)?;
    builder.sign(&ca_key, MessageDigest::sha256())?;
    let cert = builder.build();

    Ok(IssuedCert {
        cert_pem: String::from_utf8_lossy(&cert.to_pem()?).into_owned(),
        key_pem: String::from_utf8_lossy(&key.private_key_to_pem_pkcs8()?).into_owned(),
        // Server certificates carry no client role; unused for server material.
        role: Role::Admin,
    })
}

/// Verify that `cert` chains to the given CA public key.
pub fn verify_issued_by(cert_pem: &str, ca_pem: &str) -> Result<bool, TrustError> {
    let cert = parse_cert(cert_pem)?;
    let ca_cert = parse_cert(ca_pem)?;
    let ca_pub: PKey<Public> = ca_cert.public_key().map_err(TrustError::OpenSsl)?;
    cert.verify(&ca_pub).map_err(TrustError::OpenSsl)
}

/// A broker-side denylist of disabled client identities. Enabling immediate
/// disabling is a separate broker store operation; this type defines the
/// membership semantics and serialization.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct IdentityDenylist {
    disabled: Vec<String>,
}

impl IdentityDenylist {
    pub fn new() -> Self {
        Self::default()
    }

    /// Immediately disable an identity (by certificate Common Name).
    pub fn disable(&mut self, common_name: &str) {
        if !self.disabled.iter().any(|cn| cn == common_name) {
            self.disabled.push(common_name.to_string());
        }
    }

    /// Re-enable a previously disabled identity.
    pub fn enable(&mut self, common_name: &str) {
        self.disabled.retain(|cn| cn != common_name);
    }

    pub fn is_disabled(&self, common_name: &str) -> bool {
        self.disabled.iter().any(|cn| cn == common_name)
    }

    pub fn disabled_count(&self) -> usize {
        self.disabled.len()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn transport_ca_is_self_signed_ca_and_signs_clients() {
        let ca = generate_transport_ca("keywright-transport-ca").unwrap();
        let cert = parse_cert(&ca.cert_pem).unwrap();
        let ca_pub: PKey<Public> = cert.public_key().unwrap();
        assert!(cert.verify(&ca_pub).unwrap());
        assert_eq!(
            cert.subject_name().try_cmp(cert.issuer_name()).unwrap(),
            std::cmp::Ordering::Equal
        );

        let client = issue_client_cert(&ca, "pi-agent-1", Role::Agent).unwrap();
        assert!(verify_issued_by(&client.cert_pem, &ca.cert_pem).unwrap());
    }

    #[test]
    fn role_round_trips_through_cert_extension() {
        let ca = generate_transport_ca("ca").unwrap();
        for role in [Role::Agent, Role::Admin] {
            let cert = issue_client_cert(&ca, "identity", role).unwrap();
            let parsed = parse_cert(&cert.cert_pem).unwrap();
            assert_eq!(role_from_cert(&parsed).unwrap(), role);
            let ident = identity_from_cert(&parsed).unwrap();
            assert_eq!(ident.common_name, "identity");
            assert_eq!(ident.role, role);
        }
    }

    #[test]
    fn certs_without_role_extension_are_rejected() {
        // A bare self-signed cert has no role extension.
        let rogue = generate_transport_ca("rogue").unwrap();
        let cert = parse_cert(&rogue.cert_pem).unwrap();
        assert!(matches!(role_from_cert(&cert), Err(TrustError::NoIdentity)));
    }

    #[test]
    fn server_cert_is_serverauth_and_resolves_sans() {
        let ca = generate_transport_ca("ca").unwrap();
        let server = issue_server_cert(&ca, &["localhost", "broker.local"]).unwrap();
        assert!(verify_issued_by(&server.cert_pem, &ca.cert_pem).unwrap());
        let parsed = parse_cert(&server.cert_pem).unwrap();
        let sans = parsed
            .subject_alt_names()
            .expect("server cert must carry SANs")
            .iter()
            .filter_map(|g| g.dnsname().map(|s| s.to_string()))
            .collect::<Vec<_>>();
        assert!(sans.contains(&"localhost".to_string()));
        assert!(sans.contains(&"broker.local".to_string()));
        // Server certs have no client role and must not authenticate as one.
        assert!(matches!(
            role_from_cert(&parsed),
            Err(TrustError::NoIdentity)
        ));
    }

    #[test]
    fn foreign_certs_do_not_verify_against_our_ca() {
        let ca = generate_transport_ca("ours").unwrap();
        let other = generate_transport_ca("theirs").unwrap();
        let client = issue_client_cert(&other, "attacker", Role::Agent).unwrap();
        assert!(!verify_issued_by(&client.cert_pem, &ca.cert_pem).unwrap());
    }

    #[test]
    fn denylist_disables_immediately_and_re_enables() {
        let mut d = IdentityDenylist::new();
        d.disable("pi-agent-1");
        assert!(d.is_disabled("pi-agent-1"));
        assert!(!d.is_disabled("admin-1"));
        d.disable("pi-agent-1"); // idempotent
        assert_eq!(d.disabled_count(), 1);
        d.enable("pi-agent-1");
        assert!(!d.is_disabled("pi-agent-1"));
        assert_eq!(d.disabled_count(), 0);
    }
}
